MAP
    NAME "SS_MAP_SARR_INTERVENCION_SARRO"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
            'ows_title' 'Intervenciones_sarro'
            "wfs_getfeature_formatlist" "gml,geojson"
            "wfs_enable_request" "*"
            "gml_featureid" "id_sarro_agua"
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_intervencion_sarro.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_SARR_INTERVENCION_SARRO"
        PROJECTION
            'init=epsg:32614'
        END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "gm_sarro_agua from l_intervenciones_sarro using unique id_sarro_agua using srid=32614"
        TYPE POINT
        TOLERANCE 8
        TOLERANCEUNITS PIXELS
        #MAXSCALE 25000
        CLASSITEM "ds_intervencion"
        CLASS
            NAME 'Intervencion de Linea'
            EXPRESSION 'linea'
            STYLE
                SYMBOL "square"
                SIZE 20
                COLOR 090 004 207
                OUTLINECOLOR 090 004 207
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 090 004 207
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
        CLASS
            NAME 'Intervencion de Crucero'
            EXPRESSION 'crucero'
            STYLE
                SYMBOL "triangle"
                SIZE 20
                COLOR 255 174 000
                OUTLINECOLOR 255 174 000
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 10
                COLOR 255 174 000
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP